<?php
declare(strict_types=1);require_once __DIR__.'/bootstrap.php';admin_require_login();
$admin=$GLOBALS['currentAdmin'];$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){admin_csrf_check();try{if(!empty($_FILES['profile_image']['name'])){$f=$_FILES['profile_image'];if($f['error']!==UPLOAD_ERR_OK||$f['size']>3*1024*1024)throw new RuntimeException('Choose an image under 3 MB.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$types=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($types[$mime]))throw new RuntimeException('Use a JPG, PNG or WEBP image.');$dir=__DIR__.'/../uploads/profiles';if(!is_dir($dir))mkdir($dir,0755,true);$name='admin-'.(int)$admin['id'].'-'.bin2hex(random_bytes(5)).'.'.$types[$mime];if(!move_uploaded_file($f['tmp_name'],$dir.'/'.$name))throw new RuntimeException('Could not save the profile image.');$path='uploads/profiles/'.$name;$pdo->prepare('UPDATE users SET profile_image=? WHERE id=?')->execute([$path,(int)$admin['id']]);$_SESSION['flash']='Profile picture updated.';redirect('profile.php');}else throw new RuntimeException('Select a profile picture first.');}catch(Throwable $e){$errors[]=$e->getMessage();}}
admin_page_start('My profile');foreach($errors as $error):?><div class="alert alert-danger"><?=e($error)?></div><?php endforeach;?><div class="panel" style="max-width:620px"><div class="d-flex align-items-center gap-3 mb-4"><?php if(!empty($admin['profile_image'])):?><img src="../<?=e($admin['profile_image'])?>" class="admin-profile-preview" alt="Admin profile picture"><?php else:?><span class="admin-profile-preview admin-avatar-placeholder"><i class="bi bi-person-fill"></i></span><?php endif;?><div><h2 class="h5 mb-1"><?=e($admin['full_name'])?></h2><div class="text-secondary"><?=e($admin['email'])?></div></div></div><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label class="form-label" for="profile_image">Upload profile picture</label><input class="form-control mb-3" type="file" name="profile_image" id="profile_image" accept="image/png,image/jpeg,image/webp" required><div class="form-text mb-3">JPG, PNG or WEBP; maximum 3 MB.</div><button class="btn btn-primary">Save profile picture</button></form></div><?php admin_page_end();?>